  const guides=(kind:'food'|'recommended',record:typeof source)=>GuideSnapshotSchema.parse({version:1,kind,source:{url:kind==='food'?FOOD_SOURCE_URL:THEME_SOURCE_URL,licenseUrl:'https://www.data.go.kr/ugs/selectPortalPolicyView.do',credit:'TEST ONLY',collectedAt:themeTestStamp},languages:SUPPORTED_LOCALES.map(locale=>({locale,total:locale==='ko'?1:0,records:locale==='ko'?[record]:[]}))});
  const attraction=(id:string,name:string,lat:number)=>({locale:'ko',fetchedAt:themeTestStamp,record:AttractionRecordSchema.parse({sourceId:id,title:name,originalTitle:name,districtRaw:'검증 구역',coordinates:{lat,lng:129.1},imageUrl:null,descriptionRaw:'개발 검사 전용 관광지. 운영 자료로 사용하지 않는다.',holidayInfoRaw:null,addressRaw:'검증용 주소',warnings:[]})});
  const inputs={recommended:guides('recommended',source),food:guides('food',food),attractions:RouteAttractionSourcesSchema.parse({version:1,source:'readonly-existing-attraction-database',sourceUrl:'https://www.data.go.kr/data/15063481/openapi.do',exportedAt:themeTestStamp,records:[attraction('11','첫 장소',35.1),attraction('12','둘째 장소',35.101)]})};
  const places=buildThemePlaceIndex(inputs);const mappings=ThemeMappingFileSchema.parse({version:1,mappings:[...places.values()].map(place=>({id:place.ref.service+'-'+place.ref.sourceId,place:place.ref,expectedName:place.name,expectedFingerprint:place.fingerprint,reviewedAliases:[],reviewedAt:'2026-11-14',reviewMethod:'assistant-source-evidence',identityNote:'독립된 검증 fixture의 명시적 ID와 이름/좌표를 대조한다.'}))});
  const templates=ThemeTemplateFileSchema.parse({version:1,templates:[{id:'test-course',sourceId:'901',sourceLocale:'ko',expectedFingerprint:themeRecordFingerprint(source),scope:'full-source',title:'검증 코스',themeTags:['검증'],mode:'source-unspecified',reviewedAt:'2026-11-14',reviewMethod:'assistant-source-evidence',orderEvidence:{kind:'declared-sequence',context:'검증 코스',excerpt:'첫 장소 → 둘째 장소',delimiter:'→'},steps:[{label:'첫 장소',mappingId:'attraction-11',matchKind:'exact-name',identityQuote:null,unresolvedReason:null},{label:'둘째 장소',mappingId:'attraction-12',matchKind:'exact-name',identityQuote:null,unresolvedReason:null}],foodOptions:[{mappingId:'food-11',relationship:'nearby-coordinate-option',anchorIndex:0,evidenceQuote:null,note:'직선거리로만 확인한 개발 검증 후보이며 방문 순서에 삽입하지 않는다.'}],notes:['테스트 전용이다.']}]});
